// NOTICE: This file was generated by an LLM coding system.
// Opens the Yard REPL with the starter code for one PrairieLearn variant of athlete-endorsements-slr-code.
// The ?seed= word picks the sample. Keep sampleRows() and xNew() in step with server.py in that question.

const SAMPLE_SIZE = 10;

async function sha256Hex(text) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

// The SAMPLE_SIZE rows whose sha256("<seed>:<index>") sort first, kept in file order
async function sampleRows(rows, seed) {
  const keys = await Promise.all(rows.map((_, i) => sha256Hex(`${seed}:${i}`)));
  const picked = rows.map((_, i) => i).sort((a, b) => (keys[a] < keys[b] ? -1 : 1)).slice(0, SAMPLE_SIZE);
  return picked.sort((a, b) => a - b).map((i) => rows[i]);
}

async function xNew(seed) {
  return Number(1n + (BigInt("0x" + (await sha256Hex(`${seed}:x_new`))) % 6n));
}

function parseCsv(text) {
  const [header, ...lines] = text.trim().split("\n");
  const cols = header.split(",");
  return lines.map((line) => Object.fromEntries(line.split(",").map((v, i) => [cols[i], Number(v)])));
}

async function buildCode(template, csvText, seed) {
  const rows = await sampleRows(parseCsv(csvText), seed);
  return template
    .replaceAll("{{seed}}", seed)
    .replaceAll("{{endorsements}}", rows.map((r) => r.endorsements).join(", "))
    .replaceAll("{{salaries}}", rows.map((r) => r.salary).join(", "))
    .replaceAll("{{x_new}}", String(await xNew(seed)))
    .trimEnd();
}

async function main() {
  const status = document.getElementById("status");
  const seed = new URLSearchParams(location.search).get("seed") || "";
  if (!/^[a-z]+$/.test(seed)) {
    status.textContent = "This link is missing its seed word. Go back to PrairieLearn and use the link there.";
    return;
  }
  try {
    const [template, csvText] = await Promise.all(["starter.py.tmpl", "athletes.csv"].map(async (name) => (await fetch(name)).text()));
    const repl = new URL("../../repl/index.html", location.href);
    repl.search = new URLSearchParams({ kernel: "python", toolbar: "1", execute: "0", code: await buildCode(template, csvText, seed) });
    location.replace(repl);
  } catch (err) {
    status.textContent = `Could not open the Python Yard: ${err}`;
  }
}

if (typeof module !== "undefined") {
  module.exports = { sampleRows, xNew, buildCode };
} else {
  main();
}
